     pub(crate) fn task_convergence(
         &self,
         task: &Task,
         arts: &[Artifact],
         execs: &[RoleExecution],
     ) -> Option<ConvergenceView> {
         if task.state.is_terminal() {
             return None;
         }
         let read = |a: &Artifact| self.store.read_artifact_body(a);
         let bodies = convergence::BodyCache::from_reader(&read);
