         let text = serde_json::to_string(&publication()).unwrap();
         let doc: serde_json::Value = serde_json::from_str(&text).unwrap();
         assert_eq!(doc["surface_version"].as_str().unwrap(), SURFACE_VERSION);
         assert!(doc["operations"].is_array());
     }

