+/// The two lookups every carrier edge needs, built once per fold.
+struct EdgeIndex<'a> {
+    exec_role: HashMap<Id, &'a str>,
+    artifacts: HashMap<Id, &'a Artifact>,
+}
+
+type SeenEdges = HashSet<(String, String, String, String)>;
