   "type": "object",
   "required": ["version", "requirements", "unknowns", "assumptions"],
   "properties": {
     "task_id": { "type": ["string", "null"], "description": "optional in the reply — the platform stamps the stored task id before publishing" },
     "version": { "type": "integer", "minimum": 1 },
