             "required": ["key", "title", "lead", "items"],
             "properties": {
               "key": { "type": "string", "enum": ["blocks", "nuances", "anchors", "unchecked"] },
               "title": { "type": "string" },
               "lead": { "type": "string" },
               "items": {
                 "type": "array",
                 "items": {
                   "type": "object",
