+        status_word: "пройдено",
+        revoked: false,
+        executions: [
+          {
+            id: "e-1",
+            role_slug: "analyst",
+            role_display: "analyst · v1",
+            role_version: 1,
+            agent_name: "hermes",
+            status: "COMPLETED",
+            attempt: 1,
+            started_at: "2026-11-11T10:00:00Z",
+            finished_at: "2026-11-11T10:05:00Z",
+          },
+          {
+            id: "e-2",
+            role_slug: "analyst",
+            role_display: "analyst · v2",
+            role_version: 2,
+            agent_name: "hermes",
+            status: "COMPLETED",
+            attempt: 2,
+            started_at: "2026-11-11T11:00:00Z",
+            finished_at: "2026-11-11T11:05:00Z",
+          },
+        ],
+        artifacts: [
+          {
+            id: "a-spec",
+            kind: "REQUIREMENTS_SPEC",
+            seq: 2,
+            status: "CURRENT",
+            name: "requirements-spec",
+            display: "спека · v2",
+          },
+        ],
+      },
+      {
+        id: "gate:APPROVAL",
+        kind: "gate",
+        state: "APPROVAL",
+        label: "утвердить требования",
+        display: "утвердить требования",
+        role_slug: null,
+        role_version: null,
+        status: "current",
+        status_word: "сейчас",
+        revoked: false,
+        executions: [],
+        artifacts: [],
+      },
+    ],
+    edges: [
+      {
+        from: "role:analyst",
+        to: "gate:APPROVAL",
+        kind: "transfer",
+        round: null,
+        carrier: { kind: "artifact", id: "a-spec", label: "спека · v2" },
+      },
+    ],
+    position: {
+      kind: "node",
+      anchor: "gate",
+      stage: "APPROVAL",
+      node: "gate:APPROVAL",
+      reason: null,
+      line: "на утверждении требований",
+    },
+    rework: { rounds: 2, active: false, note: "кругов доработки: 2" },
+    running: [
+      {
+        execution_id: "e-3",
+        role_slug: "reviewer",
