   // Гейт качества (REQ-QG-01): те же операции, что `devai task accept|return`;
   // ответ — ПЕРЕЧИТАННЫЙ статус с публичным `quality_gate`, локального патча нет.
   taskAccept: (id_prefix: string, rationale: string | null) =>
