diff --git a/crates/devai-ui/frontend/src/types.ts b/crates/devai-ui/frontend/src/types.ts
index 3d4e4bc..d1217f2 100644
--- a/crates/devai-ui/frontend/src/types.ts
+++ b/crates/devai-ui/frontend/src/types.ts
@@ -1,1058 +1,1196 @@
 // Типы фронтов devai-ui — зеркало serde-вывода devai-api (typed-views).
 // Имена полей snake_case: структуры devai-core/devai-api не используют
 // rename_all, enum-токены сериализуются SCREAMING_SNAKE_CASE. UI берёт
 // готовые токены состояний как данные и никогда их не перефразирует.
 import type { LanState } from "./lanState";

 export type { LanState };

 export interface SessionInfo {
   home: string;
   actor: string;
   opened_at: string;
   // homes-registry cycle: где живёт реестр (OQ-HOME-1) и честно
   // простампованный факт деградированного открытия активного дома.
   control_home: string;
   degraded_from: HomeFailure | null;
 }

 // Типизированная причина, по которой дом не открылся на bootstrap-границе
 // (R5): code — машинный токен домена (home_unavailable / home_no_store /
 // home_schema_version), home — путь, message — операторский текст.
 export interface HomeFailure {
   code: string;
   home: string;
   message: string;
 }

 export interface OpDescriptor {
   name: string;
   class: "read" | "mutation" | "registry";
   input: string;
   output: string;
   description: string;
 }

 export interface Project {
   id: string;
   name: string;
   description: string;
   repos: string[];
   created_at: string;
   updated_at: string;
 }

 export interface Task {
   id: string;
   project_id: string | null;
   title: string;
   business_description: string;
   // REQ-TN-01: human signboard of the task (analyst's name, stamped at
   // spec publication; editable by the human `task rename`). null = имени
   // ещё нет. Формальный title остаётся текстом создавшего всегда.
   human_name: string | null;
   // REQ-TN-03: the FINISHED signboard, computed ONCE by the producer
   // (`devai_core::types::Task::display_sign`, serialized as `display`):
   // human name → first sentence of the DRAFT statement → formal title.
   // The frontend renders this string verbatim and NEVER re-derives it
   // (no-read-time-rederivation): there is no client-side copy of the rule.
   display: string;
   state: string;
   return_state: string | null;
   requirements_seq: number;
   lock_version: number;
   created_at: string;
   updated_at: string;
 }

 // REQ-TN-03 / R1: the signboard comes from the API as finished data
 // (`Task.display`) — the ONE rule lives in devai-core and is computed on
 // the producer side. This file holds NO client-side copy of the rule:
 // no `firstSentence`, no re-derivation per renderer (no-read-time-
 // rederivation). Views print `task.display` / `edge.task_display`.

 export interface ContractRef {
   name: string;
   version: number;
 }

 export interface Artifact {
   id: string;
   task_id: string;
   kind: string;
   name: string;
   seq: number;
   category: string;
   status: string; // CURRENT | STALE | SUPERSEDED — хранимые данные
   sha256: string;
   size: number;
   media_type: string;
   contract: ContractRef | null;
   created_by: string;
   execution_id: string | null;
   depends_on: string[];
   created_at: string;
 }

+/** REQ-NM-01: артефакт в ответе чтения — те же поля плюс ГОТОВАЯ подпись
+ * «человеческое название вида · vN». Окно печатает `display` и не собирает
+ * её само: таблица названий — декларативная конфигурация платформы. */
+export interface ArtifactView extends Artifact {
+  display: string;
+}
+
 export interface Question {
   id: string;
   task_id: string;
   execution_id: string | null;
   text: string;
   context: string | null;
   options: string[];
   blocking: boolean;
   status: string; // OPEN | ANSWERED
   answer: string | null;
   answered_by: string | null;
   answered_at: string | null;
   created_at: string;
 }

 export interface StatusView {
   task: Task;
   allowed_operations: string[];
   current_artifacts: Artifact[];
   open_questions: Question[];
   /** REQ-QG-08/09: per-action availability at the QA gate; null outside QA. */
   quality_gate: QualityGateView | null;
   /** REQ-LV-05: RUNNING-исполнения задачи с фактом живости и готовой фразой
    * платформы — карточка отвечает «идёт ли работа» прямо из этого чтения. */
   running_executions: RunningExecutionView[];
 }

 /** One platform refusal of a QA-gate act: a stable code plus the sentence the
  * window prints verbatim (the UI never derives availability from task state). */
 export interface QualityGateDenial {
   code: string;
   text: string;
 }

 /** The QA gate's public availability (task_status, REQ-QG-08/09). */
 export interface QualityGateView {
   audit_running: boolean;
   current_report: string | null;
   open_blockers: string[];
   may_accept: boolean;
   accept_denied: QualityGateDenial | null;
   may_return: boolean;
   return_denied: QualityGateDenial | null;
 }

 export interface PipelineView {
   order: string[];
   current: string;
   position: string | null;
   position_index: number | null;
   off_spine: boolean;
   terminal: boolean;
 }

 export interface RunningExecutionView {
   id: string;
   role: string;
   role_slug: string;
   role_version: number;
   agent_name: string | null;
   started_at: string;
   elapsed_seconds: number;
   /** Владелец строки, записанный платформой при старте (REQ-SW-03). */
   owner_pid: number | null;
   owner_host: string | null;
   /** alive | dead | unknown — факт живости процесса-владельца (REQ-LV-02). */
   liveness: string;
   /** Готовая фраза платформы об этом факте: окно её печатает, не собирает. */
   liveness_line: string;
 }

 /** Строка `exec.list`: сохранённая запись исполнения (поля плоские, как в
  * JSON) плюс факт живости — он есть ТОЛЬКО у незавершённого исполнения;
  * завершённую строку платформа не проверяет вовсе (REQ-LV-06 AC4). */
 export interface ExecutionView extends RoleExecution {
+  /** REQ-NM-01: «имя роли · vN» — та же подпись, что у узла графа. */
+  role_display: string;
   liveness: string | null; // alive | dead | unknown | null
   liveness_line: string | null;
 }

 /** Ответ запуска роли (`task.run`, REQ-LV-05 AC3): исход — токен платформы,
  * слова — в `line`. Окно печатает `line` как есть, а не пересказывает
  * `started|already_running|refused` своими словами. */
 export interface RunStartOutcome {
   run_id: string;
   execution_id: string | null;
   outcome: "started" | "already_running" | "refused";
   reason: string | null;
   /** Состояние задачи, в котором просили запуск (токен платформы). */
   state: string;
   /** Готовая фраза платформы об исходе запуска. */
   line: string;
 }

 export interface ProgressView {
   task: Task;
   snapshot_at: string;
   pipeline: PipelineView;
+  /** REQ-RG-01: весь путь задачи приходит этим же чтением — поле есть всегда;
+   * карточка раскладывает готовое и второго чтения не ждёт. */
+  graph: RoleGraph;
   allowed_operations: string[];
   running_executions: RunningExecutionView[];
   /** Срез сходимости (REQ-CV-12); null только у терминальных задач. */
   convergence: ConvergenceView | null;
   /** Счётчик попыток роли без прогресса (REQ-AL-07): роль, число, предел. */
   attempt_limit: AttemptLimitView | null;
   /** Факт отказа агента (задача 01a1b60c): строка и ниже-порога, и парковки. */
   agent_failure: AgentFailureView | null;
 }

+// --- граф ролей и этапов (REQ-RG-01..06) ------------------------------
+// Поля — готовые данные платформы: порядок этапов, узлы, рёбра, позиция,
+// человеческие слова статусов. Окно раскладывает; своей таблицы
+// «состояние → узел», порядка этапов и словаря подписей у него нет.
+export interface RoleGraph {
+  stages: GraphStage[];
+  nodes: GraphNode[];
+  edges: GraphEdge[];
+  position: GraphPosition;
+  rework: ReworkLoop;
+  running: GraphRunning[];
+  waits: GraphWait[];
+  blocking_questions: number;
+  notes: string[];
+}
+
+export interface GraphStage {
+  state: string;
+  label: string;
+  executor: string;
+  gate: boolean;
+  status: "passed" | "current" | "pending";
+  status_word: string;
+}
+
+export interface GraphNode {
+  id: string;
+  kind: "role" | "gate" | "final";
+  state: string;
+  label: string;
+  display: string;
+  role_slug: string | null;
+  role_version: number | null;
+  status: "passed" | "current" | "expected";
+  status_word: string;
+  revoked: boolean;
+  executions: GraphExecution[];
+  artifacts: GraphArtifact[];
+}
+
+export interface GraphExecution {
+  id: string;
+  role_slug: string;
+  role_display: string;
+  role_version: number;
+  agent_name: string | null;
+  status: string;
+  attempt: number;
+  started_at: string;
+  finished_at: string | null;
+}
+
+export interface GraphArtifact {
+  id: string;
+  kind: string;
+  seq: number;
+  status: string;
+  name: string;
+  display: string;
+}
+
+export interface GraphCarrier {
+  kind: "artifact" | "decision" | "event";
+  id: string;
+  label: string;
+}
+
+export interface GraphEdge {
+  from: string;
+  to: string;
+  kind: string;
+  round: number | null;
+  carrier: GraphCarrier;
+}
+
+export interface GraphPosition {
+  kind: "node" | "stage" | "hold" | "off_graph";
+  anchor: "role" | "gate" | "stage" | "final";
+  stage: string | null;
+  node: string | null;
+  reason: string | null;
+  line: string;
+}
+
+export interface ReworkLoop {
+  rounds: number;
+  active: boolean;
+  note: string;
+}
+
+export interface GraphRunning {
+  execution_id: string;
+  role_slug: string;
+  role_display: string;
+  role_version: number;
+  agent_name: string | null;
+  in_path: boolean;
+  note: string | null;
+}
+
+export interface GraphWait {
+  node: string;
+  state: string;
+  requirement: string;
+  hint: string;
+  awaiting: boolean;
+  signable: boolean;
+  presentation: GraphPresentation | null;
+}
+
+export interface GraphPresentation {
+  artifact_id: string;
+  display: string;
+  status: string;
+  current: boolean;
+  note: string | null;
+}
+
 /**
  * Счётчик попыток роли без прогресса (REQ-AL-07). `line` — ОДНА фраза
  * платформы («попыток без прогресса: N из M» либо «… — без предела»); окно
  * её не собирает, чтобы числа не разошлись с решением об остановке.
  */
 export interface AttemptLimitView {
   role: string;
   attempts: number;
   limit: number | null;
   line: string;
 }

 // --- отказы агента (задача 01a1b60c, REQ-AF-01..10) ---
 // Данные платформы как есть: слова причины и действие приходят полями,
 // окно их не выводит заново. Хвост ограничен; полный текст — в строке
 // выполнения и событии agent.failed.
 export interface AgentFailureView {
   agent: string;
   class: string;
   class_word: string;
   action: string;
   series_count: number;
   threshold: number;
   window_count: number;
   total_failures: number;
   first_at: string;
   last_at: string;
   parked: boolean;
   exit_code: number | null;
   duration_ms: number | null;
   tail: string;
   output_empty: boolean;
   driver_log_tail: string | null;
   driver_log_note: string | null;
   message: string;
   basis: string;
 }

 /** Строка статуса агента — ОДНА фраза платформы (`line`), не собранная здесь. */
 export interface AgentStatusView {
   name: string;
   driver: string;
   llm_provider: string;
   model: string;
   availability: string;
   availability_word: string;
   last_class: string | null;
   last_class_word: string;
   last_failure_at: string | null;
   last_outcome_at: string | null;
   last_seen_at: string;
   failures: number;
   series: number;
   series_first_at: string | null;
   line: string;
 }

 export interface ActiveRow {
   id: string;
   task_id: string;
+  /** REQ-NM-01: человеческая вывеска задачи — первая колонка списка. */
+  task_display: string;
   role: string;
+  /** REQ-NM-01: «имя роли · vN» — первая колонка роли. */
+  role_display: string;
   role_slug: string;
   role_version: number;
   agent_name: string | null;
   started_at: string;
   elapsed_seconds: number;
   state: string;
   stale: boolean;
   stale_terminal_task: boolean;
   stale_dead_owner: boolean;
   owner_pid: number | null;
   owner_host: string | null;
   owner_liveness: string; // alive | dead | unknown
   /** Готовая фраза платформы о живости (та же, что печатает CLI). */
   liveness_line: string;
   branch: string | null;
   worktree: string | null;
   /** REQ-QG-09 AC3: «идёт аудит» for a live quality audit, null otherwise. */
   note: string | null;
 }

 export interface ActiveSnapshot {
   snapshot_at: string;
   rows: ActiveRow[];
 }

 // Contract lexicon (rework R3/R4): these tokens are declared ONCE in
 // `crates/devai-core/vocab.json`; the unions below are GENERATED from that
 // data by `crates/devai-ui/build.rs` into `./vocab.generated.ts` and only
 // re-exported here. Do not hand-write a token here — edit vocab.json and
 // rebuild; `ts_types_match_the_rust_vocabulary` in `src/commands.rs` fails if
 // the generated file stops matching the Rust enums.
 import type { CheckStateToken, HumanItemKind } from "./vocab.generated";
 export type { CheckStateToken, HumanItemKind } from "./vocab.generated";

 export interface HumanFormItem {
   id: string;
   kind: HumanItemKind;
   summary: string;
   // The COMPLETE visible row, formatted once in Rust at assembly; the panel
   // prints it verbatim (rework R3: no second wording, no second precision).
   line: string;
   site: string;
   score: number | null;
   weight: number | null;
   importance: number | null;
   ratified_by?: string;
   reason?: string;
   evidence?: string[];
 }

 export interface HumanFormGroup {
   key: "blocks" | "nuances" | "anchors" | "unchecked";
   title: string;
   lead: string;
   items: HumanFormItem[];
 }

 export interface HumanForm {
   version: number;
   lang: string;
   headline: {
     verdict: string;
     machine_verdict: string;
     score: number;
     theta: number;
     // «S=…/1.00, порог …» — already formatted by the one Rust formatter.
     numbers: string;
     basis: string;
     counts: {
       blocks: number;
       nuances: number;
       anchors: number;
       unchecked: number;
       // fully passed points (1.0, no decision link): the norm, counted not
       // listed — absent in v1 forms, so optional.
       passed?: number;
     };
   };
   groups: HumanFormGroup[];
   blocked_weight: number;
   max_blocked_weight: number;
 }

 // The FIRST LAYER of a stored report (REQ-SAY-01..06): read off the stored
 // human form by the platform, printed verbatim here. It carries the human
 // wording («что нашёл аудит», чем грозит каждое замечание, что делать с
 // непроверенным) and no figure beside the saved score; every other number
 // stays in the stored row.
 export interface FirstLayerFinding {
   id: string;
   what: string;
   // Empty when the report named no site; the reader says «место не указано».
   site: string;
   // What accepting the work costs because of this finding.
   stake: string;
   // The stored machine row (id · score · weight · importance · site).
   line: string;
   evidence?: string[];
 }

 // An unchecked point is NOT a defect: it says what was missing and what to do
 // about it, in its own fields (never the finding's).
 export interface FirstLayerUnchecked {
   id: string;
   what: string;
   site: string;
   // What exactly was missing; «причина в отчёте не записана» when none was.
   missing: string;
   // What the human can do about it, or that nothing is required from them.
   action: string;
   line: string;
   evidence?: string[];
 }

 export interface FirstLayer {
   found: string;
   // Сохранённый балл работы рядом с оценкой словами (REQ-SAY-02 v4): готовая
   // строка платформы, печатается как есть — окно не форматирует числа.
   score_line: string;
   // Заголовки разделов приходят из платформы — один источник с терминалом;
   // окно печатает их как есть и не держит своих копий.
   findings_title: string;
   findings: FirstLayerFinding[];
   unchecked_title: string;
   unchecked: FirstLayerUnchecked[];
   unchecked_lead: string;
 }

 export interface ReportFreshness {
   stale: boolean;
   marker: string;
   report_seq: number;
   report_status: string;
   task_state: string;
   execution: string | null;
   execution_status: string | null;
 }

 export interface QualityReportView {
   task: string;
   artifact: string;
+  /** REQ-NM-01: «отчёт качества · vN» — готовая подпись заголовка. */
+  label: string;
   seq: number;
   contract: string;
   created_at: string;
   execution: string | null;
   status: string;
   report: unknown;
   report_text: string | null;
   // Что именно отрендерено: human_form | flat_text | corrupt_form |
   // corrupt_body | absent (rework R4) — UI различает форму и fallback, не
   // угадывая по тексту.
   source: string;
   freshness: ReportFreshness | null;
   // REQ-SAY-01..06: человеческий первый слой того же отчёта; null — у тела
   // нет читаемой человеческой формы (старый плоский текст / повреждение).
   first_layer: FirstLayer | null;
 }

 export interface TaskDependency {
   id: string;
   task_id: string;
   task_state: string;
   task_title: string;
   // Ratified OQ-TN-5: готовые вывески обоих концов ребра (правило REQ-TN-03
   // посчитано read-плоскостью); title остаётся машиночитаемым следом.
   task_display: string;
   depends_on_id: string;
   depends_on_state: string;
   depends_on_title: string;
   depends_on_display: string;
   kind: string; // parent | blocks
   actor: string;
   created_at: string;
 }

 export interface DependenciesView {
   task: Task;
   outgoing: TaskDependency[];
   incoming: TaskDependency[];
 }

 export interface Decision {
   id: string;
   task_id: string;
   kind: string;
   verdict: string;
   actor: string;
   rationale: string | null;
   refs: string[];
   created_at: string;
 }

 export interface WorkflowEvent {
   id: string;
   task_id: string | null;
   kind: string;
   actor: string;
   payload: unknown;
   created_at: string;
 }

 export interface RoleExecution {
   id: string;
   task_id: string;
   role_slug: string;
   role_version: number;
   agent_name: string | null;
   status: string; // RUNNING | COMPLETED | FAILED | CANCELLED
   inputs: string[];
   summary: string | null;
   error: string | null;
   started_at: string;
   finished_at: string | null;
   attempt?: number;
   parent_execution?: string | null;
   failure_class?: string | null;
   owner_pid?: number | null;
   owner_host?: string | null;
   owner_process_start?: number | null;
   // The v11 run stamp (REQ-MS-05): «what did this run actually use?».
   // Absent/null = «связка не записана» (a row written before the rung).
   bundle?: ExecutionBundle | null;
 }

 export interface ExecutionBundle {
   driver: string;
   llm_provider: string;
   model: string;
   reasoning: string;
 }

 // --- model-bundle section (model.snapshot / model.probe / model.switch) ---
 // REQ-MS-01/06/07: three INDEPENDENT identity fields (driver, llm_provider,
 // model), ONE status field, the declared allow-list and the stored history.
 export interface ModelBundleView {
   id: string;
   label: string;
   agent: string;
   driver: string;
   llm_provider: string;
   /** Operator word of `llm_provider`, served by the platform dictionary. */
   llm_provider_text: string;
   model: string;
   /** Operator word of `model` («не передаётся» when empty). */
   model_text: string;
   /** The level of thinking — part of the bundle (the ratified OQ-6 answer). */
   reasoning: string;
   /** Operator word of `reasoning` («связка неполна» when empty). */
   reasoning_text: string;
   probe_phrase: string;
   probe_timeout_ms: number;
   fresh_secs: number;
   active: boolean;
 }

 export interface ActiveBundleView {
   id: string | null;
   label: string | null;
   agent: string;
   driver: string;
   llm_provider: string;
   /** Operator word of `llm_provider`, served by the platform dictionary. */
   llm_provider_text: string;
   model: string;
   /** Operator word of `model` — served, never re-derived in the window. */
   model_text: string;
   /** Empty = an incomplete bundle (a run does not start). */
   reasoning: string;
   /** Operator word of `reasoning` — served, never re-derived. */
   reasoning_text: string;
   declared: boolean;
 }

 export interface BundleStatusView {
   // live | not_working | not_proven | unknown | not_selected
   state: string;
   /** The ONE operator word of `state`, served by the platform dictionary. */
   state_text: string;
   latency_ms: number | null;
   verdict: string | null;
   reason: string | null;
   /** The operator word of `reason`, from the same platform dictionary. */
   reason_text: string | null;
   evidence: string | null;
   evidence_at: string | null;
   freshness: string;
   /** The operator word of `freshness` (names WHICH evidence is fresh). */
   freshness_text: string;
   probe_older: boolean;
 }

 export interface ModelEventView {
   at: string;
   kind: string;
   actor: string;
   bundle_id: string | null;
   verdict: string | null;
   outcome: string | null;
   /** The operator word of `outcome` for a bundle mutation (served). */
   outcome_text?: string | null;
