//! Filesystem-backed workflow configuration (`config/` in the devai home).
//!
//! Roles, basic acceptance checks and common prompt rules are DECLARATIVE
//! data, not code: editing the YAML and re-running `devai init` bumps the
//! role version, and the next execution picks it up. The engine itself keeps
//! only the sovereignty skeleton (state machine) in code — an agent cannot
//! rewrite the workflow through config, but a human tunes the criteria.
//!
//! Layout:
//! ```text
//! config/
//!   prompts/common.yaml        # base role rules
//!   criteria/review.yaml       # basic spec-acceptance checks (reviewer)
//!   evaluation/base.yaml       # factory BASE profile (QA): gates, checks, scoring —

//! The model-bundle SURFACE of the platform API (tasks 01a1b71f and
//! 01a1be5c, REQ-MS-04..07 / REQ-MC-01..09): ONE snapshot read, ONE probe,
//! ONE switch — plus the AUTHORING door, which creates, edits and deletes a
//! DECLARED bundle from the window.
//!
//! Everything the console and the window render comes out of this module —
//! the window never walks the store and never composes several operations
//! itself. The declared allow-list is config (`models.yaml`), the active
//! record is the store's ONE marked agent row, the history is the
//! append-only `model.probe` / `model.switched` / `model.bundle_*` events,
//! and the run stamps on `role_executions` answer «what was actually used,
//! and when?».
//!
//! The authoring path is narrow on purpose: the form carries NAMES only

fn gate_document<'a>(f: &'a GraphFacts<'a>, state: &str) -> Option<(&'a Artifact, bool)> {
    let kind = match state {
        s if s == TaskState::Approval.as_str() => ArtifactKind::RequirementsSpec,
        s if s == TaskState::Qa.as_str() => ArtifactKind::QualityReport,
        _ => return None,
    };
    let candidates: Vec<&Artifact> = f.artifacts.iter().filter(|a| a.kind == kind).collect();
    if let Some(current) = candidates
        .iter()
        .find(|a| a.status == ArtifactStatus::Current)
    {
        return Some((current, true));
    }
    candidates
        .into_iter()
        .max_by_key(|a| (a.seq, a.created_at))
        .map(|a| (a, false))
}

